import{_ as t,o as s,c as o,ae as a}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"F6 — True fork/exec cross-process restart test","description":"","frontmatter":{},"headers":[],"relativePath":"plans/tasks/recovery-fork-exec.md","filePath":"plans/tasks/recovery-fork-exec.md"}'),r={name:"plans/tasks/recovery-fork-exec.md"};function d(c,e,n,i,l,h){return s(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="f6-—-true-fork-exec-cross-process-restart-test" tabindex="-1">F6 — True fork/exec cross-process restart test <a class="header-anchor" href="#f6-—-true-fork-exec-cross-process-restart-test" aria-label="Permalink to &quot;F6 — True fork/exec cross-process restart test&quot;">​</a></h1><p><strong>Branch:</strong> <code>wbs/f6-fork-exec</code><strong>Slice:</strong> 6 (WBS follow-up ladder), F6 (slice-2 follow-up) <strong>Traces to:</strong> F6 in <code>docs/plans/WBS.md</code></p><hr><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to &quot;Problem&quot;">​</a></h2><p>Slice 2 added a cross-process restart test, but it is not actually cross-process. <code>create-runtime-durability.test.ts</code> builds two <code>createRuntime({ dataDir })</code> lifetimes inside a single <code>bun test</code> process:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>firstRuntime  ── close() ──▶  secondRuntime</span></span>
<span class="line"><span>        (same V8 isolate, same module registry, same in-memory state)</span></span></code></pre></div><p>That proves the checkpoint file survives and that a second runtime can read it. It does <strong>not</strong> prove what we actually care about after a real crash: that a genuinely cold OS process, with no shared heap and no warm module cache, can open the same <code>dataDir</code> and recover.</p><p>Bugs that hide in exactly that gap include stale <code>.tmp</code> debris breaking the next write, a <code>.backup</code> never being created, checksum validation being skipped on the cold-read path, and any accidental dependency on module-level singletons surviving a restart.</p><h2 id="what-f6-ships" tabindex="-1">What F6 ships <a class="header-anchor" href="#what-f6-ships" aria-label="Permalink to &quot;What F6 ships&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Change</th></tr></thead><tbody><tr><td><code>apps/runtime/src/__tests__/create-runtime-fork-exec.test.ts</code></td><td><strong>New.</strong> 4 tests that spawn every runtime lifetime as a separate OS process.</td></tr><tr><td><code>apps/runtime/src/__tests__/helpers/fork-exec-helper.ts</code></td><td><strong>New.</strong> The spawned entry point. <code>seed</code>, <code>recover</code>, and <code>recover-corrupt</code> modes.</td></tr><tr><td><code>docs/plans/WBS.md</code></td><td>F6 section rewritten to describe what actually landed.</td></tr></tbody></table><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to &quot;Design&quot;">​</a></h2><p><code>Bun.spawnSync([&quot;bun&quot;, HELPER, ...])</code> runs each lifetime. The helper prints exactly one JSON object on stdout, so the parent test never has to scrape logs or guess at formatting.</p><ul><li><strong><code>seed</code></strong> — creates a runtime, registers a lane + session, forces a checkpoint, then calls <code>process.exit(0)</code> <strong>without</strong> <code>runtime.close()</code>. No graceful shutdown, no final checkpoint, no cleanup. It also leaves a stale <code>.tmp</code> on disk to reproduce the debris an ungraceful death leaves.</li><li><strong><code>recover</code></strong> — a cold process opens the same <code>dataDir</code>, confirms the first process&#39;s session is visible, and writes a fresh checkpoint on top.</li><li><strong><code>recover-corrupt</code></strong> — a cold process finds a primary checkpoint that is valid JSON with the right shape but a wrong checksum and a decoy session list. It must fall back to the <code>.backup</code> and return the real session.</li></ul><p>The decoy matters. With a merely unparseable primary, <code>read()</code> rejects it in its <code>catch</code> block and <code>verifyChecksum()</code> is never reached, so neutering the checksum check would go unnoticed. Swapping the session list makes &quot;did the reader actually reject the primary?&quot; observable from outside.</p><p>Both recovery tests assert that the pids involved are distinct from each other and from the test process. If the first ever regresses to in-process lifetimes, the assertion fails instead of the coverage silently evaporating. The two failure-path tests deliberately assert no pids: they are checking exit codes and error payloads, not process identity.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Result</th></tr></thead><tbody><tr><td><code>create-runtime-fork-exec.test.ts</code></td><td>4 pass, 0 fail, 35 assertions</td></tr><tr><td><code>apps/runtime/src/__tests__</code> + <code>apps/runtime/src/recovery</code></td><td>171 pass, 0 fail (167 on pristine <code>main</code> + 4 new)</td></tr><tr><td><code>bunx tsc --noEmit</code></td><td>clean</td></tr><tr><td><code>biome check</code> (2 changed files)</td><td>clean, no fixes on final pass</td></tr><tr><td><code>scripts/gate-static-analysis.ts</code></td><td>PASS, 0 findings</td></tr></tbody></table><h2 id="mutation-testing" tabindex="-1">Mutation testing <a class="header-anchor" href="#mutation-testing" aria-label="Permalink to &quot;Mutation testing&quot;">​</a></h2><p>Harness mutates <strong>production source only</strong> (<code>recovery/checkpoint.ts</code>), never the test file. Deleting an assertion from a passing test still passes, so test-file mutations are meaningless by construction.</p><table tabindex="0"><thead><tr><th>ID</th><th>Mutation</th><th>Result</th></tr></thead><tbody><tr><td>M1</td><td>skip <code>cleanStaleTempFiles()</code></td><td><strong>ESCAPED</strong> — see below</td></tr><tr><td>M2</td><td>skip <code>fsync</code> before rename</td><td><strong>ESCAPED</strong> — see below</td></tr><tr><td>M3</td><td>non-atomic write (no temp + rename)</td><td>caught</td></tr><tr><td>M4</td><td>stop computing the checksum</td><td>caught</td></tr><tr><td>M5</td><td>stop backing up the previous checkpoint</td><td>caught</td></tr><tr><td>M6</td><td><code>read()</code> never falls back to the backup</td><td>caught</td></tr><tr><td>M7</td><td><code>verifyChecksum()</code> always accepts</td><td>caught</td></tr><tr><td>M8</td><td><code>read()</code> returns <code>null</code> unconditionally</td><td>caught</td></tr></tbody></table><p><strong>6/8 caught.</strong> The two survivors are real, and worth stating plainly:</p><ul><li><strong>M1</strong> is unobservable by construction. <code>write()</code> calls <code>fs.writeFile(tempPath, ...)</code>, which truncates the same <code>.tmp</code> path the cleanup step would have unlinked, and the subsequent <code>rename</code> removes it either way. <code>cleanStaleTempFiles()</code> is redundant on the happy path. An early version of this test asserted &quot;no <code>.tmp</code> remains&quot; and passed for the wrong reason; that assertion is now labelled as such in the helper rather than presented as cleanup coverage.</li><li><strong>M2</strong> cannot be caught without simulating a power cut, which is out of scope for a test suite. The <code>fsync</code> is still correct and worth keeping.</li></ul><p>Neither was addressed by weakening the test or by loosening the harness.</p>`,23)])])}const m=t(r,[["render",d]]);export{u as __pageData,m as default};
